public static class ManagedBlockExtension {
    [DllImport("Netapi32.dll",CharSet=CharSet.Unicode)]static extern int NetGetJoinInformation(string server,out IntPtr name,out int status);
    [DllImport("Netapi32.dll")]static extern int NetApiBufferFree(IntPtr memory);
    public static bool DomainJoined(){IntPtr name;int status;int code=NetGetJoinInformation(null,out name,out status);if(name!=IntPtr.Zero)NetApiBufferFree(name);return code==0&&status==3;}
    public static Uri Https(string value){Uri uri;if(!Uri.TryCreate(value,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.UserInfo.Length!=0||uri.Fragment.Length!=0)throw new ArgumentException(L.T("Use um endereço HTTPS público sem senha ou fragmento.","Use a public HTTPS address without a password or fragment."));return uri;}
    static byte[] Join(params byte[][] parts){using(var stream=new MemoryStream()){foreach(var part in parts)stream.Write(part,0,part.Length);return stream.ToArray();}}
    static byte[] Der(byte type,byte[] value){var length=new List<byte>();int n=value.Length;if(n<128)length.Add((byte)n);else{var raw=new List<byte>();while(n>0){raw.Insert(0,(byte)(n&255));n>>=8;}length.Add((byte)(128|raw.Count));length.AddRange(raw);}return Join(new[]{type},length.ToArray(),value);}
    static byte[] Integer(byte[] bytes){int start=0;while(start<bytes.Length-1&&bytes[start]==0)start++;byte[] value=bytes.Skip(start).ToArray();if(value.Length==0||(value[0]&128)!=0)value=Join(new byte[]{0},value);return Der(2,value);}
    public static byte[] PublicDer(RSAParameters parameters){byte[] rsa=Der(0x30,Join(Integer(parameters.Modulus),Integer(parameters.Exponent)));return Der(0x30,Join(new byte[]{0x30,0x0d,0x06,0x09,0x2a,0x86,0x48,0x86,0xf7,0x0d,0x01,0x01,0x01,0x05,0x00},Der(3,Join(new byte[]{0},rsa))));}
    static byte[] Varint(int number){var bytes=new List<byte>();do{byte next=(byte)(number&127);number>>=7;if(number>0)next|=128;bytes.Add(next);}while(number>0);return bytes.ToArray();}
    static byte[] Field(int number,byte[] value){return Join(Varint((number<<3)|2),Varint(value.Length),value);}
    static int ReadVar(byte[] bytes,ref int at){int result=0;for(int shift=0;shift<28;shift+=7){if(at>=bytes.Length)throw new InvalidDataException("Truncated CRX header");int value=bytes[at++];result|=(value&127)<<shift;if((value&128)==0)return result;}throw new InvalidDataException("Invalid CRX varint");}
    static Dictionary<int,byte[]> Fields(byte[] data){var result=new Dictionary<int,byte[]>();int at=0;while(at<data.Length){int tag=ReadVar(data,ref at);if((tag&7)!=2)throw new InvalidDataException("Unsupported CRX field");int length=ReadVar(data,ref at);if(length<0||length>data.Length-at||result.ContainsKey(tag>>3))throw new InvalidDataException("Invalid CRX field");result[tag>>3]=data.Skip(at).Take(length).ToArray();at+=length;}return result;}
    static byte[] Zip(IDictionary<string,byte[]> files){
        using(var data=new MemoryStream())using(var writer=new BinaryWriter(data)){var rows=new List<Tuple<byte[],uint,uint,uint>>();foreach(var file in files.OrderBy(x=>x.Key,StringComparer.Ordinal)){byte[] name=Encoding.UTF8.GetBytes(file.Key);uint crc=CloneCore.Crc32(file.Value,0,file.Value.Length),size=(uint)file.Value.Length,offset=(uint)data.Position;rows.Add(Tuple.Create(name,crc,size,offset));writer.Write(0x04034b50u);writer.Write((ushort)20);writer.Write((ushort)0x800);writer.Write((ushort)0);writer.Write((ushort)0);writer.Write((ushort)0x21);writer.Write(crc);writer.Write(size);writer.Write(size);writer.Write((ushort)name.Length);writer.Write((ushort)0);writer.Write(name);writer.Write(file.Value);}
            uint central=(uint)data.Position;foreach(var row in rows){writer.Write(0x02014b50u);writer.Write((ushort)20);writer.Write((ushort)20);writer.Write((ushort)0x800);writer.Write((ushort)0);writer.Write((ushort)0);writer.Write((ushort)0x21);writer.Write(row.Item2);writer.Write(row.Item3);writer.Write(row.Item3);writer.Write((ushort)row.Item1.Length);for(int i=0;i<4;i++)writer.Write((ushort)0);writer.Write(0u);writer.Write(row.Item4);writer.Write(row.Item1);}
            uint centralLength=(uint)data.Position-central;writer.Write(0x06054b50u);writer.Write((ushort)0);writer.Write((ushort)0);writer.Write((ushort)rows.Count);writer.Write((ushort)rows.Count);writer.Write(centralLength);writer.Write(central);writer.Write((ushort)0);writer.Flush();return data.ToArray();}
    }
    static byte[] SignatureMessage(byte[] signed,byte[] archive){return Join(Encoding.ASCII.GetBytes("CRX3 SignedData\0"),BitConverter.GetBytes(signed.Length),signed,archive);}
    public static ManagedExtensionPackage Build(string source,string output,string updateUrl,string downloadUrl,string version,RSACryptoServiceProvider key){
        updateUrl=Https(updateUrl).AbsoluteUri;downloadUrl=Https(downloadUrl).AbsoluteUri;if(!Regex.IsMatch(version??"",@"^(0|[1-9][0-9]{0,4})(\.(0|[1-9][0-9]{0,4})){1,3}$")||version.Split('.').Any(x=>Int32.Parse(x)>65535))throw new ArgumentException("Invalid extension version");
        var json=new JavaScriptSerializer();var manifest=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(source,"manifest.json")));byte[] publicKey=PublicDer(key.ExportParameters(false)),digest;using(var sha=SHA256.Create())digest=sha.ComputeHash(publicKey);byte[] idBytes=digest.Take(16).ToArray();string id=String.Concat(idBytes.SelectMany(x=>new[]{(char)('a'+(x>>4)),(char)('a'+(x&15))}));
        manifest["version"]=version;manifest["key"]=Convert.ToBase64String(publicKey);manifest["update_url"]=updateUrl;var files=new Dictionary<string,byte[]>{{"manifest.json",Encoding.UTF8.GetBytes(json.Serialize(manifest))}};
        foreach(string name in new[]{"rules.json","blocked.html"}){string path=Path.Combine(source,name);if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("Extension file is a link");byte[] value=File.ReadAllBytes(path);if(value.Length>1048576)throw new IOException("Extension file too large");files[name]=value;}
        byte[] zip=Zip(files),signed=Field(1,idBytes),signature=key.SignData(SignatureMessage(signed,zip),CryptoConfig.MapNameToOID("SHA256"));byte[] header=Join(Field(2,Join(Field(1,publicKey),Field(2,signature))),Field(10000,signed)),package=Join(Encoding.ASCII.GetBytes("Cr24"),BitConverter.GetBytes(3),BitConverter.GetBytes(header.Length),header,zip);
        Directory.CreateDirectory(output);string file=Path.Combine(output,"ouo-block.crx");File.WriteAllBytes(file,package);XNamespace ns="http://www.google.com/update2/response";new XDocument(new XElement(ns+"gupdate",new XAttribute("protocol","2.0"),new XElement(ns+"app",new XAttribute("appid",id),new XElement(ns+"updatecheck",new XAttribute("codebase",downloadUrl),new XAttribute("version",version))))).Save(Path.Combine(output,"updates.xml"));
        string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(package)).Replace("-","");
        File.WriteAllText(Path.Combine(output,"PUBLICAR.txt"),"OuO • publicação da página de bloqueio\r\n\r\nEnvie updates.xml e ouo-block.crx aos endereços HTTPS escolhidos. Configure .crx como application/x-chrome-extension. Não publique a chave privada: ela permanece protegida no perfil do usuário. Guarde uma cópia da chave protegida e o perfil original para futuras atualizações. Aumente a versão a cada nova lista/aparência publicada.\r\n\r\nID: "+id+"\r\nVersão: "+version+"\r\nSHA-256: "+hash+"\r\nManifesto: "+updateUrl+"\r\nPacote: "+downloadUrl+"\r\n\r\nInstalação obrigatória de extensão hospedada fora da loja exige ambiente corporativo compatível. Computadores comuns continuam com bloqueio nativo ou instalação manual. Administradores ainda podem reverter políticas. Publicar na loja requer conta de desenvolvedor e análise da loja.\r\n",new UTF8Encoding(true));
        return new ManagedExtensionPackage{Id=id,Version=version,File=file,UpdateUrl=updateUrl,DownloadUrl=downloadUrl,Hash=hash,PublicKey=key.ToXmlString(false)};
    }
    public static bool Verify(byte[] package,ManagedExtensionPackage expected){
        try{if(package.Length<12||Encoding.ASCII.GetString(package,0,4)!="Cr24"||BitConverter.ToInt32(package,4)!=3)return false;int size=BitConverter.ToInt32(package,8);if(size<0||size>16384||size>package.Length-12)return false;Dictionary<int,byte[]> fields=Fields(package.Skip(12).Take(size).ToArray()),proof=Fields(fields[2]),signed=Fields(fields[10000]);byte[] pub=proof[1],hash;using(var sha=SHA256.Create())hash=sha.ComputeHash(pub);if(!signed[1].SequenceEqual(hash.Take(16)))return false;string id=String.Concat(signed[1].SelectMany(x=>new[]{(char)('a'+(x>>4)),(char)('a'+(x&15))}));if(id!=expected.Id)return false;using(var key=new RSACryptoServiceProvider()){key.PersistKeyInCsp=false;key.FromXmlString(expected.PublicKey);if(!PublicDer(key.ExportParameters(false)).SequenceEqual(pub))return false;return key.VerifyData(SignatureMessage(fields[10000],package.Skip(12+size).ToArray()),CryptoConfig.MapNameToOID("SHA256"),proof[2]);}}
        catch{return false;}
    }
    public static RSACryptoServiceProvider SigningKey(){string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OuO","ExtensionSigning","key.dpapi");Directory.CreateDirectory(Path.GetDirectoryName(path));var key=new RSACryptoServiceProvider(2048,new CspParameters(24));key.PersistKeyInCsp=false;
        if(File.Exists(path))key.FromXmlString(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(path),null,DataProtectionScope.CurrentUser)));
        else File.WriteAllBytes(path,ProtectedData.Protect(Encoding.UTF8.GetBytes(key.ToXmlString(true)),null,DataProtectionScope.CurrentUser));return key;}
    static byte[] Fetch(string address,int limit){ServicePointManager.SecurityProtocol|=(SecurityProtocolType)3072;var request=(HttpWebRequest)WebRequest.Create(Https(address));request.AllowAutoRedirect=false;request.Timeout=15000;request.ReadWriteTimeout=15000;using(var response=(HttpWebResponse)request.GetResponse()){if(response.StatusCode!=HttpStatusCode.OK)throw new IOException("Hosting must return HTTP 200 without redirects");using(var input=response.GetResponseStream())using(var output=new MemoryStream()){var buffer=new byte[8192];int size;while((size=input.Read(buffer,0,buffer.Length))>0){if(output.Length+size>limit)throw new IOException("Hosted extension size limit exceeded");output.Write(buffer,0,size);}return output.ToArray();}}}
    public static void VerifyPublished(ManagedExtensionPackage package){
        using(var input=new MemoryStream(Fetch(package.UpdateUrl,1048576)))using(var reader=XmlReader.Create(input,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null})){XNamespace ns="http://www.google.com/update2/response";var app=XDocument.Load(reader).Descendants(ns+"app").Single(x=>(string)x.Attribute("appid")==package.Id);var update=app.Element(ns+"updatecheck");if(update==null||(string)update.Attribute("version")!=package.Version||(string)update.Attribute("codebase")!=package.DownloadUrl)throw new InvalidDataException("Published update manifest differs from the prepared package");}
        byte[] bytes=Fetch(package.DownloadUrl,5242880);string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","");if(hash!=package.Hash||!Verify(bytes,package))throw new InvalidDataException("Published package or CRX signature differs");
    }
    public static string Merge(string existing,string id,string updateUrl){if(!Regex.IsMatch(id??"","^[a-p]{32}$"))throw new InvalidDataException("Invalid extension ID");Https(updateUrl);var json=new JavaScriptSerializer();var root=String.IsNullOrWhiteSpace(existing)?new Dictionary<string,object>():json.Deserialize<Dictionary<string,object>>(existing);if(root==null)throw new InvalidDataException("Invalid ExtensionSettings");if(root.ContainsKey(id)){var prior=root[id] as Dictionary<string,object>;if(prior==null||!prior.ContainsKey("update_url")||Convert.ToString(prior["update_url"])!=updateUrl)throw new InvalidDataException("Existing extension policy needs manual review");}root[id]=new Dictionary<string,object>{{"installation_mode","force_installed"},{"update_url",updateUrl},{"override_update_url",true}};return json.Serialize(root);}
    public static string Apply(ManagedExtensionPackage package,BrowserInfo[] browsers,Journal journal){
        if(!DomainJoined())throw new InvalidOperationException(L.T("Este PC não está em domínio. Publique a extensão em uma loja oficial ou use um ambiente corporativo compatível para instalação obrigatória de extensão própria.","This PC is not domain joined. Publish the extension in an official store or use a supported enterprise environment to force-install a self-hosted extension."));
        VerifyPublished(package);var store=new WindowsRegistryStore();var result=new List<string>();foreach(var browser in browsers.Where(x=>x.Installed&&x.Id!="firefox")){var before=store.Read("HKLM",browser.PolicyPath,"ExtensionSettings");if(before.Exists&&before.Kind!=Microsoft.Win32.RegistryValueKind.String)throw new InvalidDataException("Unexpected ExtensionSettings type");journal.RegistryChange("ManagedBlock:"+browser.Id,"HKLM",browser.PolicyPath,"ExtensionSettings",Merge(before.Exists?Convert.ToString(before.Value):null,package.Id,package.UpdateUrl),Microsoft.Win32.RegistryValueKind.String);result.Add("OK • "+browser.Name+L.T(" • política preparada; reinicie e confirme a instalação no navegador."," • policy prepared; restart and confirm installation in the browser."));}return String.Join("\n",result);
    }
}
public partial class MainWindow {
    void ManagedBlockDeployment(Panel parent){
        var panel=new StackPanel();var advanced=new Expander{Header=T("Distribuição protegida em empresas","Protected enterprise deployment"),Content=panel,Foreground=Ink,Margin=new Thickness(0,8,0,0)};parent.Children.Add(advanced);
        Note(panel,"Gere um pacote assinado para hospedar e instalar por política em PCs de domínio. Uma extensão própria não fica oculta ou irremovível em qualquer computador. Nesta máquina, o bloqueio nativo continua disponível.","Create a signed package for hosting and policy deployment on domain PCs. A custom extension cannot be hidden or made unremovable on every computer. Native blocking remains available on this machine.");
        var update=Field(panel,T("Endereço HTTPS do updates.xml","HTTPS address of updates.xml"),"");var download=Field(panel,T("Endereço HTTPS do pacote .crx","HTTPS address of the .crx package"),"");var version=Field(panel,T("Versão da extensão","Extension version"),"1.0.2");var folder=Field(panel,T("Pasta para exportar","Export folder"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"OuO-Extensao"));BrowseFolder(panel,folder);var state=Text("",13,Muted);panel.Children.Add(state);ManagedExtensionPackage prepared=null;
        Row(panel,Button(T("Exportar pacote assinado","Export signed package"),()=>{string a=update.Text,b=download.Text,v=version.Text,destination=folder.Text;Work(T("Exportar extensão","Export extension"),()=>{if(!BrowserBlockPage.Exists)throw new IOException(T("Prepare a página de bloqueio antes de exportar.","Prepare the blocked page before exporting."));using(var key=ManagedBlockExtension.SigningKey())prepared=ManagedBlockExtension.Build(BrowserBlockPage.Root,Args.LocalPath(destination),a,b,v,key);return "OK • "+T("Pacote exportado. Publique os dois arquivos HTTPS antes de aplicar a política.\nID: ","Package exported. Host the two HTTPS files before applying the policy.\nID: ")+prepared.Id;},r=>{state.Text=r;state.Foreground=OutcomeBrush(r);});}),Button(T("Verificar publicação","Check hosted files"),()=>{var package=prepared;if(package==null){ShowNotice(T("Exporte um pacote primeiro.","Export a package first."));return;}Work(T("Checar extensão publicada","Check hosted extension"),()=>{ManagedBlockExtension.VerifyPublished(package);return "OK • "+T("Publicação e assinatura conferidas.","Hosted files and signature verified.");},r=>{state.Text=r;state.Foreground=OutcomeBrush(r);});}),Button(T("Solicitar instalação protegida","Request protected installation"),()=>{var package=prepared;if(package==null||!RequireAdmin())return;if(!Confirm(T("Preparar instalação obrigatória da página de bloqueio nos navegadores Chromium detectados? A política será salva no histórico e o navegador poderá indicar gerenciamento pela organização.","Set up mandatory blocked-page installation in detected Chromium browsers? Policy will be backed up in history and the browser may display organization management.")))return;Work(T("Implantar página de bloqueio","Deploy blocked page"),()=>ManagedBlockExtension.Apply(package,BrowserExtensions.Detect(),journal),r=>{state.Text=r;state.Foreground=OutcomeBrush(r);});}),Button(T("Restaurar políticas desta extensão","Restore this extension's policies"),()=>{if(!RequireAdmin()||!Confirm(T("Restaurar as políticas da página de bloqueio gravadas pelo OuO?","Restore blocked-page policies saved by OuO?")))return;Work(T("Restaurar extensão gerenciada","Restore managed extension"),()=>journal.UndoPrefix("ManagedBlock:"),r=>{state.Text=r;state.Foreground=OutcomeBrush(r);});}));
    }
